    TFNProvenance.add(DATASET_NAME: DATASET_NAME, &fbb)
    TFNProvenance.add(DATASET_URL: DATASET_URL, &fbb)
    TFNProvenance.add(DATASET_EPOCH: DATASET_EPOCH, &fbb)
    TFNProvenance.add(DATASET_CID: DATASET_CID, &fbb)
    TFNProvenance.add(SOURCE_URL: SOURCE_URL, &fbb)
    TFNProvenance.add(SOURCE_QUERY: SOURCE_QUERY, &fbb)
    TFNProvenance.add(RETRIEVED_AT: RETRIEVED_AT, &fbb)
    TFNProvenance.add(LICENSE: LICENSE, &fbb)
    TFNProvenance.add(LICENSE_URL: LICENSE_URL, &fbb)
    TFNProvenance.add(ATTRIBUTION: ATTRIBUTION, &fbb)
    TFNProvenance.add(NON_COMMERCIAL_ONLY: NON_COMMERCIAL_ONLY, &fbb)
    TFNProvenance.add(SHARE_ALIKE: SHARE_ALIKE, &fbb)
    TFNProvenance.add(NATIVE_ID: NATIVE_ID, &fbb)
    TFNProvenance.add(NATIVE_MODIFIED: NATIVE_MODIFIED, &fbb)
    return TFNProvenance.endTFNProvenance(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
