///  Transport Facility Node
public struct TFN: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$TFN" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: TFN.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let ID: VOffset = 4
    static let PLACE_ID: VOffset = 6
    static let FACILITY_TYPE: VOffset = 8
    static let NAME: VOffset = 10
    static let DESIGNATORS: VOffset = 12
    static let COUNTRY_CODE: VOffset = 14
    static let ELEVATION_M: VOffset = 16
    static let ELEVATION_PUBLISHED: VOffset = 18
    static let MAGNETIC_VARIATION_DEG: VOffset = 20
    static let OPERATING_SURFACES: VOffset = 22
    static let MAXIMUM_DRAFT_M: VOffset = 24
    static let ANCHORAGE_DEPTH_M: VOffset = 26
    static let HARBOR_TYPE: VOffset = 28
    static let SHELTER_AFFORDED: VOffset = 30
    static let SOURCE: VOffset = 32
  }

  ///  Publisher-stable identifier for this facility record.
  public var ID: String! { let o = _accessor.offset(VT.ID); return _accessor.string(at: o) }
  public var IDSegmentArray: [UInt8]! { return _accessor.getVector(at: VT.ID) }
  ///  `$GNP.ID` of the gazetteer place carrying this facility's name set
  ///  and location. Location is joined, never re-published here.
  public var PLACE_ID: String? { let o = _accessor.offset(VT.PLACE_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var PLACE_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PLACE_ID) }
  ///  Kind of facility.
  public var FACILITY_TYPE: tfnFacilityType { let o = _accessor.offset(VT.FACILITY_TYPE); return o == 0 ? .unspecified : tfnFacilityType(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  Operational display name, verbatim, when it differs from the place
  ///  name in `$GNP`.
  public var NAME: String? { let o = _accessor.offset(VT.NAME); return o == 0 ? nil : _accessor.string(at: o) }
  public var NAMESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.NAME) }
  ///  Every designator the facility answers to, scheme-tagged.
  public var DESIGNATORS: FlatbufferVector<TFNDesignator> { return _accessor.vector(at: VT.DESIGNATORS, byteSize: 4) }
  ///  ISO 3166-1 alpha-2 country code, uppercase, as the source states it.
  public var COUNTRY_CODE: String? { let o = _accessor.offset(VT.COUNTRY_CODE); return o == 0 ? nil : _accessor.string(at: o) }
  public var COUNTRY_CODESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.COUNTRY_CODE) }
  ///  Field or reference elevation, metres above mean sea level as the
  ///  source publishes it. Zero means unpublished, never sea level; a
  ///  facility at sea level is distinguished by ELEVATION_PUBLISHED.
  public var ELEVATION_M: Double { let o = _accessor.offset(VT.ELEVATION_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  ELEVATION_M carries a published value.
  public var ELEVATION_PUBLISHED: Bool { let o = _accessor.offset(VT.ELEVATION_PUBLISHED); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  Magnetic variation at the facility, degrees, positive east, as the
  ///  source publishes it. NaN when unpublished.
  public var MAGNETIC_VARIATION_DEG: Double { let o = _accessor.offset(VT.MAGNETIC_VARIATION_DEG); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  The operating surfaces of the facility.
  public var OPERATING_SURFACES: FlatbufferVector<TFNOperatingSurface> { return _accessor.vector(at: VT.OPERATING_SURFACES, byteSize: 4) }
  ///  Maximum vessel draft the facility accepts, metres.
  public var MAXIMUM_DRAFT_M: Double { let o = _accessor.offset(VT.MAXIMUM_DRAFT_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Depth of water at the principal anchorage, metres.
  public var ANCHORAGE_DEPTH_M: Double { let o = _accessor.offset(VT.ANCHORAGE_DEPTH_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Harbor type token, verbatim as the source publishes it.
  public var HARBOR_TYPE: String? { let o = _accessor.offset(VT.HARBOR_TYPE); return o == 0 ? nil : _accessor.string(at: o) }
  public var HARBOR_TYPESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.HARBOR_TYPE) }
  ///  Shelter afforded token, verbatim as the source publishes it.
  public var SHELTER_AFFORDED: String? { let o = _accessor.offset(VT.SHELTER_AFFORDED); return o == 0 ? nil : _accessor.string(at: o) }
  public var SHELTER_AFFORDEDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.SHELTER_AFFORDED) }
  ///  Dataset lineage and licence. Required.
  public var SOURCE: TFNProvenance! { let o = _accessor.offset(VT.SOURCE); return TFNProvenance(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startTFN(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 15) }
  public static func add(ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ID, at: VT.ID) }
  public static func add(PLACE_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PLACE_ID, at: VT.PLACE_ID) }
  public static func add(FACILITY_TYPE: tfnFacilityType, _ fbb: inout FlatBufferBuilder) { fbb.add(element: FACILITY_TYPE.rawValue, def: 0, at: VT.FACILITY_TYPE) }
  public static func add(NAME: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: NAME, at: VT.NAME) }
  public static func addVectorOf(DESIGNATORS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: DESIGNATORS, at: VT.DESIGNATORS) }
  public static func add(COUNTRY_CODE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: COUNTRY_CODE, at: VT.COUNTRY_CODE) }
  public static func add(ELEVATION_M: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ELEVATION_M, def: 0.0, at: VT.ELEVATION_M) }
  public static func add(ELEVATION_PUBLISHED: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ELEVATION_PUBLISHED, def: false,
   at: VT.ELEVATION_PUBLISHED) }
  public static func add(MAGNETIC_VARIATION_DEG: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MAGNETIC_VARIATION_DEG, def: 0.0, at: VT.MAGNETIC_VARIATION_DEG) }
  public static func addVectorOf(OPERATING_SURFACES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: OPERATING_SURFACES, at: VT.OPERATING_SURFACES) }
  public static func add(MAXIMUM_DRAFT_M: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MAXIMUM_DRAFT_M, def: 0.0, at: VT.MAXIMUM_DRAFT_M) }
  public static func add(ANCHORAGE_DEPTH_M: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ANCHORAGE_DEPTH_M, def: 0.0, at: VT.ANCHORAGE_DEPTH_M) }
  public static func add(HARBOR_TYPE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: HARBOR_TYPE, at: VT.HARBOR_TYPE) }
  public static func add(SHELTER_AFFORDED: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SHELTER_AFFORDED, at: VT.SHELTER_AFFORDED) }
  public static func add(SOURCE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOURCE, at: VT.SOURCE) }
  public static func endTFN(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4, 32]); return end }
  public static func createTFN(
    _ fbb: inout FlatBufferBuilder,
    IDOffset ID: Offset,
    PLACE_IDOffset PLACE_ID: Offset = Offset(),
    FACILITY_TYPE: tfnFacilityType = .unspecified,
    NAMEOffset NAME: Offset = Offset(),
    DESIGNATORSVectorOffset DESIGNATORS: Offset = Offset(),
    COUNTRY_CODEOffset COUNTRY_CODE: Offset = Offset(),
    ELEVATION_M: Double = 0.0,
    ELEVATION_PUBLISHED: Bool = false,
    MAGNETIC_VARIATION_DEG: Double = 0.0,
    OPERATING_SURFACESVectorOffset OPERATING_SURFACES: Offset = Offset(),
    MAXIMUM_DRAFT_M: Double = 0.0,
    ANCHORAGE_DEPTH_M: Double = 0.0,
    HARBOR_TYPEOffset HARBOR_TYPE: Offset = Offset(),
    SHELTER_AFFORDEDOffset SHELTER_AFFORDED: Offset = Offset(),
    SOURCEOffset SOURCE: Offset
  ) -> Offset {
    let __start = TFN.startTFN(&fbb)
    TFN.add(ID: ID, &fbb)
    TFN.add(PLACE_ID: PLACE_ID, &fbb)
    TFN.add(FACILITY_TYPE: FACILITY_TYPE, &fbb)
    TFN.add(NAME: NAME, &fbb)
    TFN.addVectorOf(DESIGNATORS: DESIGNATORS, &fbb)
    TFN.add(COUNTRY_CODE: COUNTRY_CODE, &fbb)
    TFN.add(ELEVATION_M: ELEVATION_M, &fbb)
    TFN.add(ELEVATION_PUBLISHED: ELEVATION_PUBLISHED, &fbb)
    TFN.add(MAGNETIC_VARIATION_DEG: MAGNETIC_VARIATION_DEG, &fbb)
    TFN.addVectorOf(OPERATING_SURFACES: OPERATING_SURFACES, &fbb)
    TFN.add(MAXIMUM_DRAFT_M: MAXIMUM_DRAFT_M, &fbb)
    TFN.add(ANCHORAGE_DEPTH_M: ANCHORAGE_DEPTH_M, &fbb)
    TFN.add(HARBOR_TYPE: HARBOR_TYPE, &fbb)
    TFN.add(SHELTER_AFFORDED: SHELTER_AFFORDED, &fbb)
    TFN.add(SOURCE: SOURCE, &fbb)
    return TFN.endTFN(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.ID, fieldName: "ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PLACE_ID, fieldName: "PLACE_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.FACILITY_TYPE, fieldName: "FACILITY_TYPE", required: false, type: tfnFacilityType.self)
    try _v.visit(field: VT.NAME, fieldName: "NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.DESIGNATORS, fieldName: "DESIGNATORS", required: false, type: ForwardOffset<Vector<ForwardOffset<TFNDesignator>, TFNDesignator>>.self)
    try _v.visit(field: VT.COUNTRY_CODE, fieldName: "COUNTRY_CODE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ELEVATION_M, fieldName: "ELEVATION_M", required: false, type: Double.self)
    try _v.visit(field: VT.ELEVATION_PUBLISHED, fieldName: "ELEVATION_PUBLISHED", required: false, type: Bool.self)
    try _v.visit(field: VT.MAGNETIC_VARIATION_DEG, fieldName: "MAGNETIC_VARIATION_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.OPERATING_SURFACES, fieldName: "OPERATING_SURFACES", required: false, type: ForwardOffset<Vector<ForwardOffset<TFNOperatingSurface>, TFNOperatingSurface>>.self)
    try _v.visit(field: VT.MAXIMUM_DRAFT_M, fieldName: "MAXIMUM_DRAFT_M", required: false, type: Double.self)
    try _v.visit(field: VT.ANCHORAGE_DEPTH_M, fieldName: "ANCHORAGE_DEPTH_M", required: false, type: Double.self)
    try _v.visit(field: VT.HARBOR_TYPE, fieldName: "HARBOR_TYPE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SHELTER_AFFORDED, fieldName: "SHELTER_AFFORDED", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SOURCE, fieldName: "SOURCE", required: true, type: ForwardOffset<TFNProvenance>.self)
    _v.finish()
  }
